const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sourceWords = value => String(value??'').replaceAll('供应商行业','东方财富行业分类').replaceAll('供应商分类','东方财富行业分类').replaceAll('供应商净额','东方财富估算净额').replaceAll('供应商','数据来源');
const num = (value, digits=2) => Number.isFinite(value) ? value.toLocaleString('zh-CN', {minimumFractionDigits:digits,maximumFractionDigits:digits}) : '—';
const signed = value => Number.isFinite(value) ? (value>0?'+':'')+num(value) : '—';
const pct = value => Number.isFinite(value) ? signed(value)+'%' : '—';
const tone = value => value>0?'up':value<0?'down':'';
const money = value => Number.isFinite(value) ? num(value/1e8) : '—';
const safeLink = value => {try {const u=new URL(value);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}};
const timeText = value => value && !Number.isNaN(new Date(value).valueOf()) ? new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+' 北京时间' : '未记录';
const stateMark = value => `<span class="state ${['启动候选','强势延续观察','可考虑参与'].includes(value)?'active':['衰退预警','暂不参与','回避'].includes(value)?'warning':''}">${esc(value||'未研究')}</span>`;
const empty = (title, text) => `<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`;
const views = ['overview','sectors','stocks','watch','history'];
let status=null, analysis=null, previous=null, comparisonMessage='', view='overview', token='', posting=false, watchDraft=null, loadSequence=0, datesKey='', finishedKey='', followUpdate=false, refreshing=false;
let sectorCode='', stockCode='', sectorMode='industries', sectorFilter='all', sectorQuery='', stockPool='research', stockFilter='all', stockQuery='', historyMode='changes', fundQuery='', conceptQuery='';
const sorts={sectors:{key:'rank',dir:1},stocks:{key:'amount',dir:-1},funds:{key:'net',dir:-1},watch:{key:'change',dir:-1}};
let composing=false, loadedVersion='', pendingStudy=null;
function readRoute(search){const q=new URLSearchParams(search);return {view:views.includes(q.get('view'))?q.get('view'):'overview',date:/^\d{4}-\d{2}-\d{2}$/.test(q.get('date')||'')?q.get('date'):'',stock:/^\d{6}$/.test(q.get('stock')||'')?q.get('stock'):'',sector:/^[\w-]+$/.test(q.get('sector')||'')?q.get('sector'):'',history:q.get('history')==='reviews'?'reviews':q.get('history')==='reports'?'reports':'changes'};}
function saveRoute(){const q=new URLSearchParams();q.set('view',view);if(analysis?.target_date)q.set('date',analysis.target_date);if(stockCode)q.set('stock',stockCode);if(sectorCode)q.set('sector',sectorCode);if(view==='history')q.set('history',historyMode);window.history.replaceState(null,'','?'+q.toString());}
const initialRoute=readRoute(window.location.search);view=initialRoute.view;stockCode=initialRoute.stock;sectorCode=initialRoute.sector;historyMode=initialRoute.history;

function snapshotDiff(current, old) {
    if (!old) return {available:false, reason:'无上一份正式存档可比较', added:[],removed:[],retained:[]};
    if (old.target_date>=current.target_date) return {available:false,reason:'比较日期无效',added:[],removed:[],retained:[]};
    if (current.decision?.version!==old.decision?.version || current.decision?.candidate_version!==old.decision?.candidate_version || (!current.decision && current.candidate_rule!==old.candidate_rule)) return {available:false,reason:'研究规则版本不同，暂停名单比较',added:[],removed:[],retained:[]};
    const rows=d=>d.decision?.stocks||d.candidates||[], code=r=>r.code||r['代码'];
    const now=new Map(rows(current).map(r=>[code(r),r])), before=new Map(rows(old).map(r=>[code(r),r]));
    return {available:true,date:old.target_date,added:[...now.values()].filter(r=>!before.has(code(r))),removed:[...before.values()].filter(r=>!now.has(code(r))),retained:[...now.values()].filter(r=>before.has(code(r)))};
}
function diff(){const d=snapshotDiff(analysis,previous);if(!d.available&&comparisonMessage)d.reason=comparisonMessage;return d;}
function appearance(code){const d=diff();if(!d.available)return {text:'待比较',className:''};if(d.added.some(r=>(r.code||r['代码'])===code))return {text:'新增',className:'new'};if(d.removed.some(r=>(r.code||r['代码'])===code))return {text:'退出',className:'out'};return {text:'两份均出现',className:''};}
function evidenceFor(id){if(id.startsWith('historical:'))return analysis?.historical_evidence?.[id.slice(11)]||null;if(id==='decision_rules'&&analysis?.decision)return {title:'原规则研究结果',date:analysis.target_date,facts:{version:analysis.decision.version,market:analysis.decision.market,sectors:analysis.decision.sectors,stocks:analysis.decision.stocks}};const saved=analysis?.evidence?.[id];if(saved)return saved;if(id.startsWith('watch:')){const q=analysis?.watchlist_quotes?.find(q=>q.code===id.slice(6));if(q)return {title:q.name+' · 自选快照',date:analysis.target_date,facts:q};}return null;}
function sourceLinks(ids,historical=false){return (ids||[]).map(id=>historical?'historical:'+id:id).filter(id=>evidenceFor(id)).map(id=>`<button class="source-chip" data-source="${esc(id)}">${esc(evidenceFor(id).title)} ↗</button>`).join('');}
function head(title, text, action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${text}</p></div>${action}</div>`;}
function sortHead(group,key,label,numeric=false){const s=sorts[group];return `<th class="${numeric?'num':''}" aria-sort="${s.key===key?s.dir===1?'ascending':'descending':'none'}"><button data-sort="${group}" data-key="${key}">${label}</button></th>`;}
function sorted(rows,group){const s=sorts[group];return [...rows].sort((a,b)=>{const av=a[s.key],bv=b[s.key],am=av===null||av===undefined,bm=bv===null||bv===undefined;if(am||bm)return am===bm?0:am?1:-1;return s.dir*(typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'zh-CN'));});}
function setView(next){if(!views.includes(next))next='overview';view=next;closeScorePopover(false);closeEvidence();document.querySelectorAll('nav [data-view]').forEach(b=>{if(b.dataset.view===next)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});views.forEach(name=>$(name).hidden=name!==view);$('loading').hidden=true;saveRoute();document.title='市场雷达 · '+({overview:'今日判断',sectors:'板块机会',stocks:'个股研究',watch:'我的自选',history:'复盘与历史'}[view]);}
function sectors(){return (analysis?.industries||[]).map(s=>{const f=analysis.decision?.sectors?.find(r=>r.code===s.code);const old=previous?.industries?.find(r=>r.code===s.code),oldRule=previous?.decision?.sectors?.find(r=>r.code===s.code);const comparable=diff().available&&!!s.member_signature&&s.member_signature===old?.member_signature;return {...s,forecast:f,opportunity:opportunityOf(s.code),state:f?.state||'统计线索',five:f?.trend?.return5_percent,ratio:f?.trend?.amount_ratio5,countCandidates:researchStocks().filter(r=>r.industry?.code===s.code).length,shift:comparable&&Number.isFinite(old?.rank)?old.rank-s.rank:null,stateChange:comparable&&oldRule?oldRule.state===f?.state?'状态未变':oldRule.state+' → '+f?.state:'待比较'};});}
function researchStocks(){const rows=analysis?.decision?.stocks||analysis?.candidates||[];return rows.map(r=>{const code=r.code||r['代码'],q=(analysis.candidates||[]).find(q=>q['代码']===code)||analysis.evidence?.['stock:'+code]?.facts||{};return {...r,code,name:r.name||r['名称']||q['名称']||code,close:q['收盘']??r.history?.close,change:q['涨跌幅'],amount:q['成交额'],five:r.history?.return5_percent,ratio:r.history?.amount_ratio5,state:r.state||'筛选线索'};});}
function stockRows(pool=stockPool){if(pool==='screened')return (analysis?.candidates||[]).map(r=>({...r,code:r['代码'],name:r['名称'],close:r['收盘'],change:r['涨跌幅'],amount:r['成交额'],state:'筛选线索'}));if(pool==='exited')return diff().removed.map(r=>({...r,code:r.code||r['代码'],name:r.name||r['名称'],close:null,change:null,amount:null,state:'已退出当前候选'}));return researchStocks();}
function compareSummary(){const d=diff();return d.available?`<div class="compare-summary"><span>对照 ${esc(d.date)} 正式存档</span><strong>新增 ${d.added.length}</strong><strong>退出 ${d.removed.length}</strong><span>两份均出现 ${d.retained.length} · 不代表连续交易日</span><button class="link-button" data-go="history">查看变化 →</button></div>`:`<div class="compare-summary">${esc(d.reason)}。新增、退出及连续性暂不判断。</div>`;}

function renderOverview(){
    if(!analysis){$('overview').innerHTML=head('今日判断','先了解市场，再研究方向，最后检查自选')+empty('还没有可阅读的研究','点击右上角更新研究。完成前可在我的自选中添加关注的股票。');return;}
    $('overview').innerHTML=`<div class="workspace decision-workspace">${entrySummary()}${priorityResearch()}
    <details class="inline-detail decision-background"><summary>研究时点、AI状态与数据缺口</summary>${researchTiming()}<div class="market-research-pair compact-verdict">${marketResearchPanel()}</div></details>
    <details class="inline-detail supporting-data"><summary>下次复盘需要检查什么</summary>${nextDayResearch()}</details><details class="inline-detail"><summary>指数与市场事实 · 展开核对</summary>${marketPicture()}</details><div class="section-jumps"><button class="link-button" data-go="sectors">查看板块机会 →</button><button class="link-button" data-go="watch">检查我的自选 →</button></div><details class="inline-detail supporting-data"><summary>资金渠道 · 来源与金额</summary>${fundsOverview()}</details><details class="inline-detail supporting-data"><summary>海外行情 · 各资产日期与影响</summary>${internationalOverview()}</details><details class="inline-detail supporting-data"><summary>政策与事件 · 原日资料及后续消息</summary>${eventsOverview()}</details>
    <details class="inline-detail"><summary>研究依据、评分规则与数据缺口</summary>${marketDetails()}${evidenceTasks()}</details></div>`;
}

function marketDetails(){const d=analysis,r=d.decision;if(!r)return `<p class="note">${esc(d.candidate_rule||'该存档仅提供规则统计')}</p>${sourceLinks(['market','rules','limitations'])}${briefDetails()}`;const f=r.funds||{},s=r.sentiment||{};return `<div class="section"><h2>五维环境 · 原规则结果（待验证）</h2><div class="table-wrap"><table><thead><tr><th>维度</th><th class="num">评分</th><th class="num">权重</th><th>依据 / 口径</th><th>证据</th></tr></thead><tbody>${r.market.dimensions.map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${num(x.score,0)}</td><td class="num">${x.weight}%</td><td>${esc(sourceWords(x.reason))}</td><td>${sourceLinks(x.source_ids)}</td></tr>`).join('')}</tbody></table></div><p class="note">${esc(r.market.reason)}。缺失维度不补中性分；政策评分含 AI 对有限样本的主观判断。</p></div><div class="section"><h2>情绪与独立资金渠道</h2><p>涨幅≥5% ${s.large_rise_count??'—'} 只 · 跌幅≥5% ${s.large_fall_count??'—'} 只</p><p class="note">${esc(s.message)}</p><p>上交所融资余额 ${money(f.margin?.balance_cny)} 亿 · 相邻记录变化 ${money(f.margin?.change_cny)} 亿 · ${esc(f.margin?.date||'日期未取得')}</p><p class="note">${esc(sourceWords(f.mapping))}。${esc(f.national_team?.message)}</p>${sourceLinks(['market','funds'])}</div><details class="section"><summary>原报告保存的 AI 解读 · ${esc(r.ai?.status||'未生成')}</summary><div class="explain"><span class="label">AI 解读 · 推断仍需核验</span><p>${esc(r.ai?.interpretation?.market?.judgment||r.ai?.message||'没有匹配当前快照的 AI 解释。')}</p><span class="label">AI 提出的反证</span><p>${esc(r.ai?.interpretation?.counterevidence||'未提供')}</p></div></details><details class="section"><summary>研究范围、版本与数据局限</summary><p class="note">原预测 ${esc(d.prediction_id||'未记录')} · 规则 ${esc(r.version)} · 判断生成 ${timeText(r.generated_at)}</p>${(r.gaps||[]).map(x=>`<p class="note">${esc(x)}</p>`).join('')}${sourceLinks(['coverage','limitations'])}</details>`;}
function briefDetails(){const p=analysis.research_brief;if(!p)return '';return `<details><summary>已保存的 AI 完整解释</summary>${(p.brief?.sections||[]).map(s=>`<div class="explain"><h3>${esc(s.id)}</h3><span class="label">事实</span><p>${esc(s.facts)}</p><span class="label">AI 解读</span><p>${esc(s.interpretation)}</p><span class="label">反例 / 下一步</span><p>${esc(s.check)}</p>${sourceLinks(s.source_ids)}</div>`).join('')}</details>`;}

function renderSectors(){const title=head('板块机会',analysis?'比较板块强弱，打开行业查看依据、确认条件与风险':'等待正式报告');if(!analysis){$('sectors').innerHTML=title+empty('尚无正式行业结果','数据齐备后查看板块机会。');return;}
    $('sectors').innerHTML=title+`<div class="workspace"><div class="tabs" aria-label="板块数据范围">${[['industries','申万行业'],['funds','东方财富资金估算'],['concepts','概念线索']].map(([key,label])=>`<button data-sector-mode="${key}" aria-pressed="${sectorMode===key}">${label}</button>`).join('')}</div><div id="sector-detail">${sectorMode==='industries'&&sectorCode?sectorDetail():''}</div>${sectorMode==='industries'?boardPicture()+industryTable():sectorMode==='funds'?fundsTable():conceptCoverage()}</div>`;
}
function industryTable(){const rows=sorted(sectors().filter(matchesSector),'sectors');return `<div class="filters"><label>状态 <select id="sector-state" aria-label="板块状态"><option value="all">全部状态</option>${[['机会类型',['潜在启动','反转观察','趋势跟随','衰退风险']],['原规则状态',['启动候选','强势延续观察','衰退预警','等待确认','证据不足','统计线索']]].map(([label,items])=>`<optgroup label="${label}">${items.map(v=>`<option ${sectorFilter===v?'selected':''}>${v}</option>`).join('')}</optgroup>`).join('')}</select></label><label>搜索 <input id="sector-search" aria-label="搜索行业" type="search" value="${esc(sectorQuery)}" placeholder="行业名称 / 代码"></label><span class="small">${rows.length} / ${analysis.industries.length} 行业</span>${sectorQuery||sectorFilter!=='all'?'<button class="secondary" data-clear-sector>清除筛选</button>':''}</div><div class="table-wrap"><table id="industry-table"><thead><tr>${sortHead('sectors','rank','排名')}${sortHead('sectors','name','行业')}<th>机会类型 / 原规则</th>${sortHead('sectors','absolute_change_percent','当日等权',true)}${sortHead('sectors','relative','相对 / pp',true)}${sortHead('sectors','breadth','广度',true)}${sortHead('sectors','five','5日',true)}${sortHead('sectors','ratio','成交额倍数',true)}${sortHead('sectors','countCandidates','候选',true)}${sortHead('sectors','shift','排名变化',true)}</tr></thead><tbody>${rows.map(s=>`<tr class="${sectorCode===s.code?'selected':''}"><td class="num">${s.rank}</td><td><button class="link-button" data-sector="${s.code}">${esc(s.name)}</button></td><td>${esc(s.opportunity?.type||'旧报告未诊断')}<small>${esc(s.state)}</small></td><td class="num ${tone(s.absolute_change_percent)}">${pct(s.absolute_change_percent)}</td><td class="num">${signed(s.relative)}</td><td class="num">${num(s.breadth,1)}%</td><td class="num ${tone(s.five)}">${pct(s.five)}</td><td class="num">${num(s.ratio)}×</td><td class="num">${s.countCandidates}</td><td class="num">${Number.isFinite(s.shift)?s.shift>0?'↑'+s.shift:s.shift<0?'↓'+Math.abs(s.shift):'不变':'—'}</td></tr>`).join('')||'<tr><td colspan="10">没有匹配结果，请调整筛选。</td></tr>'}</tbody></table></div><p class="note">相对值为较全市场的百分点差；5日为行业指数表现。成交额倍数是当日额 / 5日均额，非日内量比。资金分类未经映射，独立查看。${diff().available?'排名变化仅比较成员一致的存档。':'无前次正式存档，变化与连续性暂不可核验。'}</p>`;}
function sectorDetail(){const s=sectors().find(s=>s.code===sectorCode);if(!s)return '<p class="note">点击行业名称，核对规则、条件与相关候选。</p>';const f=s.forecast;return `<div class="detail-title"><div><span class="eyebrow">申万一级 · ${s.count} 只成员</span><h2>${esc(s.name)} <span class="code">${s.code}</span></h2></div><div class="meta-row">${stateMark(s.state)}<button class="secondary" data-close-sector>收起详情</button></div></div><dl class="detail-metrics"><div><dt>相对排名</dt><dd>${s.rank}</dd></div><div><dt>当日成交额 / 亿</dt><dd>${money(s.amount)}</dd></div><div><dt>上涨成员</dt><dd>${num(s.breadth,1)}%</dd></div><div><dt>当前候选</dt><dd>${s.countCandidates}</dd></div></dl>${priceFactLine('sectors',s.code)}${aiDetail('sectors',s.code)}${opportunityDetail(s.code)}<div class="explain"><h3>相关研究候选</h3>${researchStocks().filter(x=>x.industry?.code===s.code).map(x=>`<p><button class="link-button" data-stock="${x.code}">${esc(x.name)}</button> <span class="code">${x.code}</span> · ${stateMark(x.state)}</p>`).join('')||'<p class="note">原报告没有该行业候选；历史名单保持原样。</p>'}</div><details class="inline-detail"><summary>原行业规则与持续时间样本</summary>${durationNote(f)}<div class="detail-body"><div><div class="explain"><h3>支持依据 · 规则</h3><p>${esc(f?.reason||'当前仅提供同日行业统计，不能据此确认启动。')}</p><span class="label">次日观察</span><p>${esc(f?.next_day||'未提供')}</p><span class="label">3–5个交易日</span><p>${esc(f?.near_term||'未提供')}</p></div><div class="explain"><h3>相关研究候选</h3>${researchStocks().filter(x=>x.industry?.code===s.code).map(x=>`<p><button class="link-button" data-stock="${x.code}">${esc(x.name)}</button> <span class="code">${x.code}</span> · ${stateMark(x.state)}</p>`).join('')||'<p class="note">没有进入研究候选的股票，不代表没有研究价值。</p>'}</div></div><div><div class="explain"><h3>确认条件</h3><p>${esc(f?.confirmation||'未提供确认条件')}</p></div><div class="explain"><h3>反证与失效</h3><p>${esc(f?.invalidation||'连续历史不足，不能解释排名变化或持续性。')}</p><p class="note">${esc(s.stateChange)} · 资金支持尚未形成同分类映射。</p></div></div></div><div>${sourceLinks(f?.source_ids||['industry:'+s.code])}</div></details>`;}
function fundsTable(){const c=analysis.research_context?.funds,all=c?.boards||analysis.decision?.funds?.board_flows||[],rows=sorted(all.filter(f=>(f.name+f.code).includes(fundQuery)).map(f=>({...f,net:f.net_cny})),'funds');return `<div class="meta-row"><strong>东方财富行业分类资金</strong><span class="small">${c?'当前金额可用 '+c.coverage.observed+'/'+c.coverage.expected:'原报告记录 '+rows.length+'/'+(analysis.decision?.funds?.board_expected??'—')} · ${esc(analysis.target_date)}</span>${sourceLinks([c?'research:funds':'funds'])}</div><div class="filters"><label>搜索 <input type="search" id="fund-search" aria-label="搜索资金分类" value="${esc(fundQuery)}"></label><span>${rows.length}/${all.length} 分类</span>${fundQuery?'<button class="secondary" data-clear-fund>清除搜索</button>':''}</div><p class="note">${esc(c?.mapping||analysis.decision?.funds?.mapping||'不同分类独立观察')}。订单分类净额不识别机构身份。${c?'原报告保存 '+c.coverage.original_observed+' 个分类；当前 '+c.coverage.conflicted+' 个金额冲突，未选择任一旧金额补值。':''}</p><div class="table-wrap"><table><thead><tr>${sortHead('funds','name','东方财富行业分类')}${sortHead('funds','net','净额 / 亿',true)}<th>日期</th><th>金额状态</th><th>来源口径</th></tr></thead><tbody>${rows.map(f=>`<tr><td>${esc(f.name)}</td><td class="num ${tone(f.net)}">${Number.isFinite(f.net)?money(f.net):windowText(f.windows?.['1'])}</td><td>${esc(f.date||analysis.target_date)}</td><td>${f.windows?.['1']?.status==='CONFLICT'?'数据冲突':Number.isFinite(f.net)?'可用':'数据不足'}</td><td class="small">东方财富 · 行业资金估算 · 亿元</td></tr>`).join('')||'<tr><td colspan="5">该日期没有合格资金记录，缺失不填零。</td></tr>'}</tbody></table></div>`;}
function conceptCoverage(){const c=opportunityData()?.concepts;if(!c?.rows?.length)return empty('概念线索尚未生成','保留原采集覆盖；没有齐备成员和行情时不补零。');const rows=c.rows.filter(r=>(r.name+r.code).includes(conceptQuery)).sort((a,b)=>(b.relative??-Infinity)-(a.relative??-Infinity));return `<div class="section"><h2>概念当日线索 <span class="count">${rows.length}/${c.rows.length}个 · 已保存成员口径</span></h2><div class="filters"><label>搜索 <input type="search" id="concept-search" aria-label="搜索概念" value="${esc(conceptQuery)}"></label>${conceptQuery?'<button class="secondary" data-clear-concept>清除搜索</button>':''}</div>${!rows.length?'<p class="note">没有匹配概念，清除搜索后查看全部。</p>':''}<p class="note">${esc(c.message)} · 行情 ${esc(c.target_date)} · 成员保存 ${esc(timeText(c.membership_at))}</p><div class="table-wrap concept-table"><table><thead><tr><th>概念</th><th class="num">成员覆盖</th><th class="num">等权涨跌</th><th class="num">相对 / pp</th><th class="num">上涨占比</th><th>流动性成员线索</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td class="num">${r.covered}/${r.count}</td><td class="num ${tone(r.absolute_change_percent)}">${pct(r.absolute_change_percent)}</td><td class="num">${signed(r.relative)}</td><td class="num">${Number.isFinite(r.breadth)?num(r.breadth,0)+'%':'—'}</td><td>${r.leaders.map(l=>researchStocks().some(s=>s.code===l.code)?`<button class="link-button" data-stock="${l.code}">${esc(l.name)}</button>`:esc(l.name)).join(' · ')}<small>仅按成交额排序，尚未核验概念受益关系</small></td></tr>`).join('')}</tbody></table></div><p class="note">无同口径概念连续历史，不给启动或持续时长判断；采集完整不等于每个概念的行情成员齐备。</p></div>`;}


function renderStocks(){if(!analysis){$('stocks').innerHTML=head('个股研究','从板块逻辑核对候选条件')+empty('暂无正式研究候选','发布完整报告后查看，当前可先维护自选。');return;}
    const rows=sorted(stockRows().filter(s=>(stockFilter==='all'||s.state===stockFilter)&&(s.name+s.code+(s.industry?.name||'')).includes(stockQuery)),'stocks');
    $('stocks').innerHTML=head('个股研究',`${researchStocks().length} 只研究候选 · 观察不等于买入`)+`<div class="workspace"><div class="tabs" aria-label="候选范围">${[['research','研究候选'],...((analysis.candidates||[]).some(s=>!researchStocks().some(r=>r.code===s['代码']))?[['screened','全部筛选线索']]:[]),['exited','退出候选']].map(([key,label])=>`<button data-pool="${key}" aria-pressed="${stockPool===key}">${label}</button>`).join('')}</div><div class="filters"><label>状态 <select id="stock-state" aria-label="股票状态"><option value="all">全部状态</option>${['观察线索','可考虑参与','等待确认','暂不参与','证据不足','筛选线索','已退出当前候选'].map(v=>`<option ${stockFilter===v?'selected':''}>${v}</option>`).join('')}</select></label><label>搜索 <input id="stock-search" aria-label="搜索股票" type="search" value="${esc(stockQuery)}" placeholder="名称 / 代码 / 行业"></label><span class="small">${rows.length} 条结果</span></div>${stockMobileList(rows)}<div class="table-wrap stock-desktop-table"><table id="stock-table"><thead><tr>${sortHead('stocks','name','股票 / 行业')}${sortHead('stocks','close','收盘 / 元',true)}${sortHead('stocks','state','原规则状态')}<th>AI独立研究意见</th>${sortHead('stocks','change','今日',true)}${sortHead('stocks','five','5日',true)}${sortHead('stocks','amount','成交额 / 亿',true)}${diff().available?'<th>名单变化</th>':''}</tr></thead><tbody>${rows.map(s=>{const a=stockPool==='screened'?{text:'规则线索',className:''}:appearance(s.code);return `<tr class="${stockCode===s.code?'selected':''}"><td><button class="link-button" data-stock="${s.code}" ${stockPool==='exited'?'data-exited="true"':''}>${esc(s.name)}</button><small>${s.code} · ${esc(s.industry?.name||'未匹配')}</small><small>${esc(s.opportunity_type||opportunityOf(s.industry?.code)?.type||'旧规则候选')}</small></td><td class="num">${num(s.close)}</td><td>${stateMark(s.state)}</td><td>${esc(stockOpinionText(s.code))}</td><td class="num ${tone(s.change)}">${pct(s.change)}</td><td class="num ${tone(s.five)}">${pct(s.five)}</td><td class="num">${money(s.amount)}</td>${diff().available?`<td><span class="change ${a.className}">${a.text}</span></td>`:''}</tr>`;}).join('')||`<tr><td colspan="${diff().available?8:7}">${stockPool==='exited'&&!diff().available?esc(diff().reason):'没有匹配的股票，请调整筛选。'}</td></tr>`}</tbody></table></div><details class="inline-detail"><summary>未提供的指标与比较范围</summary><p class="note">60日表现、日内量比及20日新高尚未包含在已保存结果中；不补算新规则。${diff().available?'名单变化仅对照已有正式存档。':'无上一份可比较正式存档，名单变化待比较。'}研究状态为存档规则结果，参与前提需在详情核对。</p></details><div id="stock-detail">${stockDetail()}</div></div>`;
}
function stockMobileList(rows){return `<div class="stock-mobile-list">${rows.map(s=>`<article><button class="link-button" data-stock="${s.code}" ${stockPool==='exited'?'data-exited="true"':''}>${esc(s.name)} · ${s.code}</button><p>原规则：${esc(s.state)} · AI：${esc(stockOpinionText(s.code))}</p><p>核心障碍：${esc(stockVerdict(s.code)?.reason||researchStatus(s.code)?.issues?.[0]?.impact||s.risks?.[0]||'独立研究与参与条件仍需核对')}</p><small>收盘 ${num(s.close)} · 当日 ${pct(s.change)} · 5日 ${pct(s.five)} · 成交额 ${money(s.amount)} 亿</small></article>`).join('')||'<p class="note">没有匹配股票，请调整筛选。</p>'}</div>`;}
function stockDetail(){const s=researchStocks().find(r=>r.code===stockCode)||stockRows('screened').find(r=>r.code===stockCode);if(!s)return '<p class="note">点击股票名称查看入选原因、参与前提与风险。</p>';const watched=(status?.watchlist||[]).some(r=>r.code===s.code);return `<div class="detail-title"><div><span class="eyebrow">${esc(s.industry?.name||'行业未匹配')}</span><h2>${esc(s.name)} <span class="code">${s.code}</span></h2></div><div class="meta-row">${stateMark(s.state)}<button class="secondary" data-add-watch="${s.code}" ${watched||status?.running||posting?'disabled':''}>${watched?'已在自选':'加入自选'}</button></div></div><p class="candidate-origin">${s.opportunity_type?'候选来源：'+esc(s.opportunity_type):'原报告候选保持原名单'}${s.industry?' · 所属板块诊断 '+esc(opportunityOf(s.industry.code)?.type||'未提供'):''}</p><p class="note">${esc(stockFundSummary(s.code))}</p>${priceFactLine('stocks',s.code)}${stockVerdict(s.code)?`<section class="stock-verdict"><h3>AI独立研究意见 · ${esc(stockVerdict(s.code).decision)}</h3><p>${esc(stockVerdict(s.code).reason)}</p><small>原参与条件：${esc(stockVerdict(s.code).release_condition)}</small></section>`:''}${stockVerdict(s.code)?`<details class="inline-detail"><summary>原完整AI研究 · ${esc(aiStamp())}</summary>${aiDetail('stocks',s.code)}</details>`:aiDetail('stocks',s.code)}<div class="detail-body"><div><div class="explain"><h3>为什么关注 · 规则依据</h3><p>${esc(s.reason||analysis.candidate_rule||'该股票进入当日筛选范围，尚无完整研究条件。')}</p>${s.industry?`<button class="link-button" data-sector="${s.industry.code}">核对 ${esc(s.industry.name)} 的板块条件 →</button>`:''}</div><div class="explain"><h3>参与前提</h3><p>${esc(s.entry?.condition||'未形成参与前提，不能据此买入。')}</p></div><dl class="detail-metrics"><div><dt>收盘 / 元</dt><dd>${num(s.close)}</dd></div><div><dt>当日涨跌</dt><dd class="${tone(s.change)}">${pct(s.change)}</dd></div><div><dt>5日表现</dt><dd class="${tone(s.five)}">${pct(s.five)}</dd></div><div><dt>成交额 / 亿</dt><dd>${money(s.amount)}</dd></div></dl><div class="explain"><h3>收盘与均线位置 · 同一价格刻度</h3>${pricePosition(s)}<p class="note">${esc(s.entry?.type||'没有已核验的买入区间')}。成交额 / 5日均额 ${num(s.ratio)}×，不等于日内量比。</p></div></div><div><div class="explain"><h3>主要风险 · 默认可见</h3><ul class="risk-list">${(s.risks?.length?s.risks:['尚未完成业务、公告及参与条件核验。']).map(r=>`<li>${esc(r)}</li>`).join('')}</ul></div><div class="explain"><h3>失效 / 重审条件</h3><p>${esc(s.exit?.condition||'未提供完整条件，保持研究观察。')}</p></div><div class="explain"><h3>原始行情与证据</h3>${sourceLinks(s.source_ids||['stock:'+s.code])}<p class="note">${esc(s.history?.source||analysis.evidence?.['stock:'+s.code]?.facts?.source||'来源见存档')} · ${esc(analysis.target_date)}</p></div></div></div>${evidenceTasks(s.code)}`;}

function watchRows(){return (analysis?.watchlist_quotes||[]).map(q=>{const r=researchStocks().find(r=>r.code===q.code),e=(analysis.enrichment?.events||[]).filter(e=>e.code===q.code),s=analysis.evidence?.['watch:'+q.code]?.facts;return {...q,code:q.code||q['代码'],name:q.name||q['名称'],close:q['收盘'],change:q['涨跌幅'],industry:r?.industry||q.industry||analysis.opportunities?.watch_industries?.[q.code]||s?.industry,state:r?.state||'未进入研究候选',research:r,events:e,flow:q.net_flow_cny};});}
function renderWatch(){const rows=sorted(watchRows(),'watch');$('watch').innerHTML=head('我的自选',analysis?`${analysis.target_date} 保存的自选行情 · 当前名单编辑后，下次更新生效`:'可以先保存名单，再更新数据')+`<div class="workspace"><p class="note">更新会取得自选名单行情；独立个股AI研究目前只覆盖本轮候选。未进入候选的自选，可先核对所属板块、主营资料与公告。</p><div id="watch-pending" class="notice" hidden></div><div class="table-wrap"><table><thead><tr>${sortHead('watch','name','股票 / 板块')}${sortHead('watch','close','收盘 / 元',true)}${sortHead('watch','change','今日',true)}<th>研究状态 / 条件</th>${sortHead('watch','flow','东方财富估算净额 / 亿',true)}<th>新变化 / 风险与催化</th><th>最近保存判断</th></tr></thead><tbody>${rows.map(s=>`<tr><td><button class="link-button" data-watch-stock="${s.code}">${esc(s.name)}</button><small>${s.code} · ${esc(s.industry?.name||'该快照未提供行业')}</small></td><td class="num">${num(s.close)}</td><td class="num ${tone(s.change)}">${pct(s.change)}</td><td>${stateMark(s.state)}<small>${esc(opportunityOf(s.industry?.code)?.type||(s.research?'参与前提仍待核验':'没有对应研究规则结果'))}</small></td><td class="num ${tone(s.flow)}">${money(s.flow)}</td><td>${s.events.length?esc(s.events[0].title):'<span class="muted">有限样本未命中，非无事件</span>'}<small>${s.research?esc(s.research.risks?.[0]||appearance(s.code).text):'未完成风险研究'}</small><small>${esc(stockFundSummary(s.code))}</small></td><td>${s.research?esc(analysis.target_date):opportunityOf(s.industry?.code)?'板块 · '+esc(analysis.target_date):'—'}</td></tr>`).join('')||'<tr><td colspan="7">该日期未保存自选行情，可先维护名单。</td></tr>'}</tbody></table></div><div id="watch-detail"></div><details class="edit-box" id="watch-editor"><summary>编辑自选名单 <span class="small">· 当前 ${(status?.watchlist||[]).length} 只</span></summary><label for="watchlist">每行一只：六位股票代码 空格 名称</label><textarea id="watchlist" spellcheck="false" aria-describedby="watch-help"></textarea><p id="watch-help" class="note">最多50只，名称可省略。保存后下次更新生效；不改写历史快照。</p><button class="primary" id="save" ${status?.running||posting?'disabled':''}>保存名单</button><p id="save-message" role="status" aria-live="polite"></p></details></div>`;$('watchlist').value=watchDraft??(status?.watchlist||[]).map(r=>r.code+' '+r.name).join('\n');updateWatchPending();}
function watchDetail(code){const s=watchRows().find(s=>s.code===code);if(!s)return;const r=s.research;$('watch-detail').innerHTML=`<div class="detail-title"><h2>${esc(s.name)} <span class="code">${s.code}</span></h2>${stateMark(s.state)}</div><div class="detail-body"><div class="explain"><h3>最近保存的判断</h3><p>${esc(r?.reason||'该股票未进入当前研究候选；未生成参与判断。')}</p>${s.industry?`<h3>所属板块条件 · 不代表该股已确认</h3>${opportunityDetail(s.industry.code)}`:''}${r?`<button class="link-button" data-stock="${s.code}">查看参与前提和失效条件 →</button>`:''}<p class="note">${esc(stockFundSummary(code))}</p><p class="note">${esc(analysis.target_date)} · 行情来源 ${esc(s.source||'未记录')}</p>${sourceLinks(['watch:'+s.code,'stock:'+s.code])}</div><div class="explain"><h3>事件与风险样本</h3><p class="note">可核对公开主营与公告样本；资料不齐不会生成买入确认。</p><a href="https://data.eastmoney.com/stockdata/${esc(s.code)}.html" target="_blank" rel="noopener">公司资料与公告入口 ↗</a>${s.events.map(e=>`<p><a href="${safeLink(e.url)}" rel="noreferrer">${esc(e.title)} ↗</a><small class="muted"> ${esc(e.date)} · ${esc(e.source)}</small></p>`).join('')||'<p>当前有限样本未命中，不能理解为没有新闻或风险。</p>'}</div></div>`;}
function updateWatchPending(){if(!analysis||!$('watch-pending'))return;const saved=(analysis.watchlist_quotes||[]).map(r=>r.code).sort().join(','),configured=(status?.watchlist||[]).map(r=>r.code).sort().join(',');$('watch-pending').hidden=saved===configured;$('watch-pending').textContent='当前名单与所选日期存档不同。行情列表展示当时名单，新名单在下次更新后生效。';}
async function addWatch(code){const rows=status?.watchlist||[],s=researchStocks().find(r=>r.code===code)||stockRows('screened').find(r=>r.code===code);if(!s||rows.some(r=>r.code===code))return;if(watchDraft!==null){$('toast').hidden=false;$('toast').textContent='自选编辑中有未保存内容，请先保存或处理草稿。';setView('watch');$('watch-editor').open=true;$('watchlist').focus();return;}await post('/api/watchlist',{text:[...rows,{code,name:s.name}].map(r=>r.code+' '+r.name).join('\n')});}

const reviewStatus = value => ({PENDING:'待到期',ABSTAIN:'未参与',MISSING_DATA:'数据不足',CALENDAR_UNKNOWN:'日历未核验',NOT_AT_SIGNAL:'后生成意见，非原预测',NOT_TRIGGERED:'未触发',UNEXECUTABLE:'无法成交',UNRESOLVED:'尚未核验',NO_VALID_ORDER:'无有效参与区间',SIMULATED:'模拟结果',EVALUATED:'已核验'}[value]||value);
function independentAIReviews(review){return `<div class="section"><h2>AI独立研究核验</h2><p class="note">后补意见按真实发表时点核验，与原规则信号、模拟交易使用独立分母；不计真实前瞻交易日。</p>${(review.ai_research_reviews||[]).map(r=>`<details class="review-row"><summary>AI研究发表 ${esc(timeText(r.issued_at))}</summary><p class="note">证据日期 ${esc(r.evidence_date)} · 收盘参考 ${esc(r.reference_date||'未核验')}。${esc(r.note||'日历未核验')}</p>${r.outcomes.map(o=>`<p class="note">${o.horizon}日 · ${esc(reviewStatus(o.status))} · 独立研究分母 ${o.denominators?.ai_research??0} · 模拟交易 0</p>${(o.ai_research||[]).map(a=>`<p>${esc(a.code)} · ${esc(a.opinion)} · ${esc(reviewStatus(a.status))} · 收盘方向变化 ${pct(a.absolute_percent)}（非交易收益）</p>`).join('')}`).join('')}</details>`).join('')||'<p class="note">尚无通过当前业务校验的独立AI研究存档，不补写历史样本。</p>'}</div>`;}
function historicalStudy(){const r=analysis?.historical_review;if(!r)return '';return `<details class="section" open><summary>${esc(analysis.target_date)} 历史再研究 · ${timeText(r.generated_at)}</summary><p class="note">仅使用当日23:59前公开的资料；晚生成，不计当时前瞻预测。原报告与当前资讯研究分别保留。</p><p>${esc(r.interpretation?.market?.judgment||r.interpretation?.summary||'研究解释未提供')}</p><p class="note">风险：${esc(r.interpretation?.market?.risk||'见已保存研究')}</p></details>`;}
function renderHistory(){const dates=status?.analysis_dates||[],review=analysis?.reviews||{};$('history').innerHTML=head('复盘与历史','保留原判断，对照后续结果；未触发、无法成交与缺失分别展示')+`<div class="workspace"><div class="tabs" aria-label="复盘范围">${[['changes','名单与判断变化'],['reviews','原判断核验'],['reports','正式历史报告']].map(([key,label])=>`<button data-history-mode="${key}" aria-pressed="${historyMode===key}">${label}</button>`).join('')}</div>${historicalStudy()}${historyMode==='changes'?historyChanges():historyMode==='reviews'?renderReviews(review):`<div class="table-wrap"><table><thead><tr><th>行情日期</th><th>发布状态</th><th>操作</th></tr></thead><tbody>${dates.map(day=>`<tr><td>${esc(day)}</td><td>${stateMark('正式发布')}</td><td><div class="history-actions"><button class="link-button" data-date="${day}">查看这天的判断 →</button><a href="/reports/market-${day}.html">原始报告 ↗</a></div></td></tr>`).join('')||'<tr><td colspan="3">还没有正式历史报告。</td></tr>'}</tbody></table></div><details class="inline-detail"><summary>早期研究草稿 · 不进入正式比较</summary>${(status?.reports||[]).filter(n=>/^market-/.test(n)&&!dates.includes(n.slice(7,-5))).map(n=>`<p><a href="/reports/${n}">${esc(n.slice(7,-5))} · 草稿 ↗</a></p>`).join('')||'<p class="note">没有额外草稿。</p>'}</details>`}</div>`;}
function historyChanges(){if(!analysis)return empty('尚无可比较的判断','正式报告发布后保留原结果。');const d=diff();if(!d.available)return empty('变化暂不可核验',d.reason+'；下一份正式存档发布后，可查看新增、退出及状态变化。');const oldMarket=previous.decision?.market?.action||'未记录',newMarket=analysis.decision?.market?.action||'未记录';const all=[...d.added.map(s=>({...s,changeLabel:'新增'})),...d.removed.map(s=>({...s,changeLabel:'退出'})),...d.retained.map(s=>({...s,changeLabel:'两份均出现'}))];return `${compareSummary()}<p>市场判断：${esc(oldMarket)} → <strong>${esc(newMarket)}</strong></p><div class="section-head"><h2>研究候选变化</h2></div><div class="table-wrap"><table><thead><tr><th>股票</th><th>名单变化</th><th>原状态</th><th>当前状态</th><th>操作</th></tr></thead><tbody>${all.map(s=>{const code=s.code||s['代码'],old=previous.decision?.stocks?.find(r=>r.code===code),now=analysis.decision?.stocks?.find(r=>r.code===code);return `<tr><td>${esc(s.name||s['名称'])} <span class="code">${code}</span></td><td>${esc(s.changeLabel)}</td><td>${esc(old?.state||'未入选')}</td><td>${esc(now?.state||'未入选')}</td><td>${now?`<button class="link-button" data-stock="${code}">当前研究 →</button>`:`<button class="link-button" data-date="${previous.target_date}">查看原日 →</button>`}</td></tr>`;}).join('')}</tbody></table></div><div class="section-head"><h2>板块状态变化</h2></div><div class="table-wrap"><table><thead><tr><th>板块</th><th>当前状态</th><th>与原存档比较</th></tr></thead><tbody>${sectors().map(s=>`<tr><td><button class="link-button" data-sector="${s.code}">${esc(s.name)}</button></td><td>${stateMark(s.state)}</td><td>${esc(s.stateChange)}</td></tr>`).join('')}</tbody></table></div><p class="note">这是名单和判断对照，不是收益归因或卖出信号。成员不一致的板块暂停比较。</p>`;}
function renderReviews(review){const records=(review.records||[]).filter(r=>!analysis||r.target_date<=analysis.target_date).slice().reverse();const renderRecord=r=>`<details class="review-row"><summary><span class="review-info"><strong>${esc(r.prediction_date||r.target_date)}</strong> · ${r.counts_as_forward?'当天统计版本':r.record_type==='OFFICIAL_FORWARD_FORECAST'?'已保存前瞻版本 · 不重复计入':'研究记录'}<small class="code"> 规则 ${esc(r.version)} · ${esc(timeText(r.issued_at))}</small></span><span class="small">${(r.outcomes||[]).map(o=>o.horizon+'日 '+reviewStatus(o.status)).join(' · ')}</span></summary><p class="note">行情基准 ${esc(r.target_date)}；原判断发出 ${timeText(r.issued_at)}；结果更新 ${timeText(r.updated_at)} · 记录 ${esc(r.id)}</p>${(r.outcomes||[]).map(o=>`<div class="review-outcome"><h3>第 ${o.horizon} 交易日 · ${esc(reviewStatus(o.status))}</h3>${o.status!=='EVALUATED'?`<p class="note">${esc(o.message)}</p>`:`<p>日期 ${esc(o.date||'未核验')} · 沪深300 ${pct(o.benchmark_percent)} · 对照覆盖 ${o.baseline?.covered??'—'}/${o.baseline?.expected??'—'}</p><div class="table-wrap"><table><thead><tr><th>板块</th><th>原信号</th><th>核验</th><th class="num">绝对</th><th class="num">超额</th></tr></thead><tbody>${(o.sectors||[]).map(s=>`<tr><td>${esc(analysis?.industries?.find(i=>i.code===s.code)?.name||s.code)}</td><td>${esc(s.state)}</td><td>${s.status==='EVALUATED'?s.hit?'成立':'未成立':esc(reviewStatus(s.status))}</td><td class="num">${pct(s.absolute_percent)}</td><td class="num">${pct(s.excess_percent)}</td></tr>`).join('')}</tbody></table></div><p class="note">独立分母：原规则信号 ${o.denominators?.rule_signals??'未记录'} · AI研究 ${o.denominators?.ai_research??'未记录'} · 可执行模拟交易 ${o.denominators?.simulated_trades??'未记录'}</p><p class="note">最大回撤 ${pct(o.market_result?.max_drawdown_percent)} · 相对信号日起点最大下行 ${pct(o.market_result?.max_signal_decline_percent)}</p>${(o.ai_research||[]).map(a=>`<p class="note">AI研究 ${esc(a.code)} · ${esc(a.opinion)} · ${esc(reviewStatus(a.status))} · 收盘方向核验 ${pct(a.absolute_percent)}（非交易收益）</p>`).join('')}${(o.stocks||[]).map(s=>`<p class="note">${esc(s.code)} · ${esc(s.reason||reviewStatus(s.status))}</p>`).join('')}`}</div>`).join('')}</details>`;const other=records.filter(r=>r.target_date===analysis?.target_date&&r.id!==analysis?.prediction_id&&!r.counts_as_forward),primary=records.filter(r=>!other.includes(r));return `${conditionReviews([analysis?.opportunity_review,...records.filter(r=>(r.outcomes||[]).some(o=>o.opportunity_conditions))])}<div class="meta-row"><strong>原判断核验</strong><span class="small">真实前瞻 ${review.forward_days??0} 日 / 初步评估门槛 ${review.preliminary_minimum_days??20} 日</span></div><p class="note">${esc(review.effect_status||'尚无足够前瞻样本')}。回放和晚生成单独标注；未核验不计胜率。</p>${primary.map(renderRecord).join('')||empty('尚无原判断核验记录','原判断发布后，等待后续交易日及合格行情。')}${other.length?`<details class="inline-detail"><summary>同日其他已保存研究版本 · ${other.length}份</summary>${other.map(renderRecord).join('')}</details>`:''}<p class="note">${esc(review.improvement_policy||'失败、未触发、无法成交和数据不足均保留。')}</p>${independentAIReviews(review)}`;}

let scoreTrigger=null;
function closeScorePopover(restore=true){$('score-popover').hidden=true;if(scoreTrigger){scoreTrigger.setAttribute('aria-expanded','false');if(restore&&scoreTrigger.isConnected)scoreTrigger.focus();}scoreTrigger=null;}
function openScorePopover(id,trigger){
    if(scoreTrigger===trigger&&!$('score-popover').hidden){closeScorePopover();return;}
    closeScorePopover(false);closeEvidence();const content=scoreExplanation(id);if(!content)return;
    $('score-content').innerHTML=content;scoreTrigger=trigger;trigger.setAttribute('aria-expanded','true');
    const panel=$('score-popover');panel.hidden=false;const rect=trigger.getBoundingClientRect();
    panel.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-panel.offsetWidth-12))+'px';
    panel.style.top=Math.max(12,Math.min(rect.bottom+8,window.innerHeight-panel.offsetHeight-12))+'px';
    $('score-close').focus();
}
let evidenceTrigger=null;
const narrowEvidence=window.matchMedia('(max-width:1250px)');
function evidenceModality(){const modal=!$('evidence-panel').hidden&&narrowEvidence.matches;document.querySelector('main').inert=modal;document.querySelector('header').inert=modal;$('evidence-panel').setAttribute('role',modal?'dialog':'complementary');if(modal)$('evidence-panel').setAttribute('aria-modal','true');else $('evidence-panel').removeAttribute('aria-modal');}
function closeEvidence(){document.body.classList.remove('evidence-open');$('evidence-panel').hidden=true;$('evidence-scrim').hidden=true;evidenceModality();if(evidenceTrigger?.isConnected)evidenceTrigger.focus();evidenceTrigger=null;}
narrowEvidence.addEventListener('change',evidenceModality);
function evidenceFields(id,f){id=id.replace(/^historical:/,'');const field=(label,value)=>`<dt>${esc(label)}</dt><dd>${esc(value??'未提供')}</dd>`;
    if(id==='participation')return field('行情日期',f.target_date)+field('原市场态度',f.market_action)+field('完整总分',num(f.score))+field('缺失评分项',f.missing_dimensions?.join('、')||'无')+field('改变判断条件',f.change_condition)+field('已有主营资料',`${f.stocks?.filter(s=>s.business).length??0}/${f.stocks?.length??0}`)+(f.limits||[]).map(i=>field(i.item,i.impact+'；处理：'+i.action)).join('');
    if(/^research:\d{6}$/.test(id))return field('股票',f.name+' '+f.code)+field('原研究状态',f.rule_state)+field('主营事实',f.business||'未取得')+field('资料日期与口径',(f.business_date||'未取得')+(f.business_late?' · 后补资料，不是行情日当时证据':''))+field('历史样本条数',f.history_samples)+field('公告样本',`${f.notices?.length??0}条 · ${f.notice_date||'日期未取得'} · ${f.notice_scope}`)+(f.issues||[]).map(i=>field(i.item,i.impact+'；处理：'+i.action)).join('');
    if(id==='opportunities')return field('诊断版本',f.version)+field('行业扫描',f.sectors?.length)+field('AI深读范围',f.selected_codes?.length)+Object.entries(f.counts||{}).map(([name,value])=>field(name,value)).join('')+field('趋势条件',(f.market?.trend_checks||[]).map(c=>c.label+'：'+(c.met===true?'满足':c.met===false?'未满足':'未知')).join('；'))+field('未知项',f.market?.limits)+field('范围',f.scope)+field('历史候选',f.candidate_note||'机会类型选股');
    if(id.startsWith('opportunity:'))return field('机会类型',f.type)+field('原规则状态',f.original_state)+field('行业指数当日',pct(f.index_change_percent))+field('指数5日',pct(f.five_percent))+field('广度',num(f.breadth,1)+'%')+field('成交额 / 5日均额',num(f.amount_ratio5))+field('失效固定参考 / 点',num(f.signal_reference))+field('参考定义',f.reference_name)+(f.invalidation_checks||[]).map(c=>field(c.label,c.met===true?'已满足':c.met===false?'未满足':'未知')).join('')+(f.confirmation_checks||[]).map(c=>field(c.label,c.met===true?'已满足':c.met===false?'未满足':'未知')).join('');
    if(id==='decision_rules')return field('规则版本',f.version)+field('原参与态度',f.market?.action)+field('环境分（非概率）',num(f.market?.score,0))+field('判断依据',f.market?.reason);
    if(id==='history:indices')return Object.entries(f).map(([code,t])=>field(({sh000001:'上证指数',sz399001:'深证成指',sh000300:'沪深300'}[code]||code)+' · 收盘',num(t.close))+field('MA20',num(t.ma20))+field('5日表现',pct(t.return5_percent))+field('日期 / 来源',(t.date||'未记录')+' / '+(t.source||'未记录'))).join('');
    if(id==='market')return field('市场状态',f.regime)+field('上涨广度',num(f.breadth_percent,1)+'%')+field('等权涨跌',pct(f.equal_weight_change_percent))+field('成交额 / 亿',money(f.turnover_cny));
    if(id.startsWith('industry:'))return field('成员数',f.count)+field('行业涨跌',pct(f.absolute_change_percent))+field('相对市场 / pp',signed(f.relative))+field('上涨广度',num(f.breadth,1)+'%')+field('排名',f.rank)+field('成交额 / 亿',money(f.amount))+field('比较日',f.comparison_date||'无可比较存档')+field('比较状态',f.comparison_status||'未记录');
    if(id.startsWith('stock:')||id.startsWith('watch:'))return field('代码',f.code||f['代码'])+field('收盘 / 元',num(f['收盘']))+field('涨跌',pct(f['涨跌幅']))+field('成交额 / 亿',money(f['成交额']))+field('来源',f.source)+field('行情日期',f['日期']||analysis.target_date)+field('源时间',f['源时间']||'未记录')+field('规则范围',id.startsWith('watch:')?'自选名单快照；研究条件需另行核对':analysis.candidate_rule||'研究名单见个股详情');
    if(id.startsWith('history:stock:'))return field('原研究状态',f.state)+field('行业',f.industry?.name)+field('参与前提',f.entry?.condition)+field('MA5观察 / 元',num(f.entry?.ma5_reference))+field('风险',(f.risks||[]).join('；'))+field('失效条件',f.exit?.condition);
    if(id.startsWith('history:industry:'))return field('5日指数表现',pct(f.trend?.return5_percent))+field('历史样本条数',f.trend?.samples)+field('来源',f.trend?.source)+field('持续区间样本',f.duration?.sample_count)+field('定义',f.duration?.definition)+field('说明',f.duration?.message);
    if(id==='funds')return field('东方财富资金估算覆盖',`${f.board_flows?.length??'—'}/${f.board_expected??'—'}`)+field('分类口径',sourceWords(f.mapping))+field('融资余额 / 亿',money(f.margin?.balance_cny))+field('融资日期',f.margin?.date)+field('融资相邻记录变化 / 亿',money(f.margin?.change_cny))+field('国家队',f.national_team?.message)+field('局限',sourceWords((f.limitations||[]).join('；')));
    if(id==='coverage')return field('有效行情 / 存档范围',`${f.coverage?.valid_quotes??'—'}/${f.coverage?.universe??'—'}`)+field('缺失',f.coverage?.missing)+Object.entries(f.snapshots||{}).map(([k,v])=>field(k,v)).join('')+field('发布门槛','只读正式发布存档；覆盖针对存档范围');
    if(id==='events')return field('已取得事件样本',f.events?.length??'未提供')+(f.events||[]).slice(0,12).map(e=>field(e.date+' · '+e.source,e.title)+`<dd><a href="${safeLink(e.url)}" rel="noreferrer">原始来源 ↗</a></dd>`).join('');
    return `<pre>${esc(JSON.stringify(f,null,2))}</pre>`;
}
function openEvidence(id,trigger){const e=evidenceFor(id);if(!e)return;evidenceTrigger=trigger;$('evidence-content').innerHTML=`<span class="eyebrow">${id.startsWith('historical:')?'上次AI研究证据':'当前已保存证据'} · ${esc(e.date)} · 非实时</span><h3>${esc(e.title)}</h3><span class="label">${id==='opportunities'||id.startsWith('opportunity:')||id==='decision_rules'||id==='participation'||id.startsWith('research:')?'规则状态与已存事实 · 核验事项另列':'事实 / 原始记录 / 指标口径'}</span><dl>${evidenceFields(id,e.facts||{})}</dl>${sourceLinks(e.facts?.source_ids?.filter(key=>key!==id.replace(/^historical:/,'')),id.startsWith('historical:'))}<details class="inline-detail"><summary>查看完整原始记录</summary><pre>${esc(JSON.stringify(e.facts,null,2))}</pre></details><p class="source-note">规则与 AI 判断见对应研究详情，并与原始事实区分。未核验信息不作为已知事实，成交额不等于净流入。</p><a href="/reports/market-${analysis.target_date}.html">该日原始报告 ↗</a>`;$('evidence-panel').hidden=false;$('evidence-scrim').hidden=false;document.body.classList.add('evidence-open');evidenceModality();$('evidence-close').focus();}

function render(){closeEvidence();renderOverview();renderSectors();renderStocks();renderWatch();renderHistory();updateSnapshotLabel();setView(view);}
function updateSnapshotLabel(){const meta=analysis?.publication;const label=analysis?`收盘研究 · 非实时${meta?.generated_at?' · 原报告 '+timeText(meta.generated_at):''}`:'暂无正式报告';$('snapshot-label').textContent=label;}
function updateOptions(){const mode=document.querySelector('input[name="update-mode"]:checked').value;$('update-date-row').hidden=mode==='current';const day=$('update-date').value||analysis?.target_date||'';const latest=status?.analysis_dates?.[0]||'自动核验最近交易日';$('update-scope').textContent=mode==='current'?`行情：自动核验最近已收盘交易日（已有 ${latest}）；资讯：截至本次更新。`: `行情：${day||'请选择日期'}；资讯：仅限该日23:59前公开的资料。结果保存为历史再研究，不改写原预测。`;const p=status?.ai_settings||{},b=status?.ai_budget,blocked=!p.enabled||!p.key_configured||b?.new_request_possible===false;const labels={current:'更新当前研究',supplement:'补齐 '+day+' 研究',replay:'生成 '+day+' 复盘'};$('update-start').textContent=blocked?labels[mode]+' · 仅资料与缓存':labels[mode];$('update-budget').textContent=(blocked?'不能新增AI请求；可处理资料并核对已有缓存，缓存不匹配时保留历史研究。':'可尝试新增AI；调用前仍按完整输入与证据重新核对预算。')+(blocked&&b?.reset_at?' 下一次预算恢复：'+timeText(b.reset_at)+'。':'')+(b?' 剩余 '+b.remaining_tokens+' tokens；请求次数不限。':'')+(b?.error?' '+b.error:'');$('update-task').textContent=($('update-options').dataset.opened==='true'?'沿用当前选择：':'本次任务：')+labels[mode]+'；'+(mode==='current'?'保存当前补充研究。':'保存历史再研究，不计当时预测。');}
function scheduleText(schedule){
    const s=schedule?.summary||{},a=s.latest_attempt,ok=s.latest_success;
    return (schedule?.installation?.interval==='5 minutes'?'任务已注册':'任务未就绪')+' · '+(schedule?.enabled?'已开启':'已暂停')+'。最近尝试：'+(a?timeText(a.attempted_at)+' · '+({DONE:'完成',RUNNING:'处理中',NEEDS_ATTENTION:'需处理',RETRY_PENDING:'待续采'}[a.status]||a.status):'未取得记录')+'。最近关键事实合格研究：'+(s.latest_qualified_research?timeText(s.latest_qualified_research):'尚未取得新版校验通过记录')+'。最近成功任务：'+(ok?timeText(ok.finished_at):'未取得记录')+'。'+(s.next_check_estimate?'下一检查约 '+timeText(s.next_check_estimate)+'（需电脑开机、联网并登录）。':'')+(s.next_research_window?'下一交易日研究窗口 '+timeText(s.next_research_window)+'。':'')+(s.today_trading===false?'当前为休市日；任务未运行不等于失败。':'')+(s.calendar_status==='NEEDS_UPDATE'?'交易日历待更新，无法确定下次研究日期。':'');
}
function renderUpdateProgress(){const busy=!!(status?.running||posting),p=(!posting&&status?.progress)||{completed:0,total:4,steps:['检查行情','补充证据','分析与核验','保存结果']};$('update-track').hidden=!busy&&!(status?.exit_code>0&&Number.isInteger(p.completed)&&p.completed>0);$('research-progress').max=p.total;$('research-progress').value=p.completed;$('update-track').classList.toggle('is-running',busy);$('update-track').classList.toggle('has-failed',status?.exit_code>0);$('progress-steps').textContent=`已完成 ${p.completed}/${p.total} 步 · ${p.steps.join(' → ')}`;$('progress-time').textContent=busy?`已用 ${Math.floor((status?.elapsed_seconds||0)/60)}分${(status?.elapsed_seconds||0)%60}秒`:status?.exit_code>0?'本轮未完成':'已完成';$('research-progress').setAttribute('aria-valuetext',`已完成${p.completed}个步骤，共${p.total}步；${status?.stage||'准备更新'}`);$('update-start').disabled=busy;}
async function loadAnalysis(day){const sequence=++loadSequence;closeEvidence();views.forEach(name=>$(name).hidden=true);$('loading').hidden=false;$('loading').textContent='正在读取 '+day+' 的正式存档…';let data;try{const response=await fetch('/api/analysis?date='+encodeURIComponent(day));data=await response.json();if(!response.ok)throw Error(data.error||'读取失败');if(sequence!==loadSequence)return;}catch(error){if(sequence!==loadSequence)return;analysis=null;previous=null;render();$('connection').textContent=error.message+'；请选择其他正式日期或检查数据与设置。';return;}
    let old=null,message='';const prior=(status?.analysis_dates||[]).find(date=>date<day);if(prior){try{const response=await fetch('/api/analysis?date='+prior);if(!response.ok)throw Error();old=await response.json();}catch{message='前次正式存档读取失败，当前报告仍可阅读';}}if(sequence!==loadSequence)return;analysis=data;previous=old;comparisonMessage=message;loadedVersion=data.analysis_version||'';if(!data.industries?.some(s=>s.code===sectorCode))sectorCode='';if(!researchStocks().some(s=>s.code===stockCode)&&!stockRows('screened').some(s=>s.code===stockCode))stockCode='';render();}
async function refresh(){if(refreshing)return;refreshing=true;try{const response=await fetch('/api/status');if(!response.ok)throw Error();const fresh=await response.json();status=fresh;token=status.token;const aiLine=document.querySelector('.decision-ai-state');if(aiLine&&analysis)aiLine.textContent=aiResearchState();$('connection').textContent=(status.data_errors||[]).join('；');
    for(const id of ['run','date','refresh-snapshots','schedule-enabled','ai-retry','observations-update'])$(id).disabled=status.running||posting;if($('save'))$('save').disabled=status.running||posting;
    $('update-open').disabled=!!(status.running||posting||status.config_error);$('update-open').textContent=status.running?'更新中…':'更新研究';$('update-progress').textContent=status.running?(status.stage||'正在检查行情与已有研究')+' · 可以继续阅读上次结果':Number.isInteger(status.exit_code)?(status.exit_code===0?(status.update_result?status.update_result.data+'；'+status.update_result.evidence+'；AI '+(status.update_result.ai==='READY'?(status.update_result.cached?'复用合格缓存':'已生成并核验'):'未生成：'+status.update_result.message):'研究处理已结束。'+aiResearchState()+'。'):'本轮更新未完成，已保留原研究。请在数据与设置查看原因。'):'更新前可选择当前研究、补齐交易日或指定日期复盘。';renderUpdateProgress();$('run-state').textContent=status.running?'正在更新 · 阅读仍使用原正式存档':status.exit_code===null?'可按需更新，已有合格结果自动复用':status.exit_code===0?'本轮已结束，请核对发布状态与缺口':'本轮异常结束，原正式报告保留';
    const last=status.last_run||{},c=last.coverage||{};$('coverage').textContent=last.target_date?`${last.target_date} · ${c.universe?'行情 '+(c.valid_quotes??'—')+'/'+c.universe+' · 缺口 '+(c.missing??'—'):'股票范围未知，不能核验覆盖或缺口'}`:'尚无采集记录';$('scope-date').textContent='股票范围快照：'+(last.snapshots?.['股票范围']||'未知')+'；覆盖针对存档范围。';$('ai-state').textContent=analysis?aiResearchState():'请先选择已保存的研究，查看对应AI状态';const params=status.ai_settings||{},used=Object.entries(status.ai_usage?.days||{}).at(-1);$('ai-parameters').textContent=`软件版本 ${status.product_version}。日常配置：${params.model||'未启用'} / ${params.reasoning_effort||'—'} / 输出上限 ${params.max_tokens??'—'} tokens · Key ${params.key_configured?'已配置':'未配置'}。请求次数不限；UTC每日 token 预算 ${params.max_total_tokens_per_day??'—'} tokens；${used?used[0]+' 已调用 '+used[1].requests+' 次、已知 '+used[1].total_tokens+' tokens、用量未知 '+used[1].unknown_usage_requests+' 次':'暂无调用记录'}。`;const actual=analysis?.ai_review;if(actual?.business_status==='PASSED'&&actual.parameters){const p=actual.parameters;$('ai-parameters').textContent+=` 最近合格实际请求：${p.model} / ${p.reasoning_effort} / 输出上限 ${p.max_tokens} tokens。`;}const budgetUsed=status.ai_budget?.new_request_possible===false;$('ai-retry').disabled=!!(status.running||posting||status.config_error||!analysis||!params.enabled||!params.key_configured||budgetUsed);$('ai-retry').textContent=budgetUsed?'今日模型预算已用尽（UTC次日恢复）':'重试所选日期的AI研究（调用模型）';$('log').textContent=(status.log||[]).join('\n')||'尚未启动';$('schedule-enabled').checked=!!status.schedule?.enabled;$('schedule-state').textContent=scheduleText(status.schedule);if($('update-options').open)updateOptions();const forecast=status.forecast||{},stamp=forecast.issued_at||analysis?.publication?.generated_at;const meta=[stamp?'生成 '+timeText(stamp):'',forecast.market_baseline_date||analysis?.target_date?'行情基准 '+(forecast.market_baseline_date||analysis.target_date):'',forecast.external_information_cutoff?'信息截止 '+timeText(forecast.external_information_cutoff):''].filter(Boolean);const separate=forecast.source_snapshot_id&&analysis?.prediction_id!==forecast.source_snapshot_id?' · 当前页面为其他研究版本，原预测见复盘与历史':'';const autoPre=status.schedule?.state?.slots?.[forecast.prediction_date+':pre'];const autoFailure=autoPre?.status==='NEEDS_ATTENTION'?' · 本轮盘前自动更新未成功，保留已保存研究':'';$('forecast-state').textContent=forecastLabel(forecast)+(meta.length?' · '+meta.join(' · '):'')+separate+autoFailure;
    const dates=status.analysis_dates||[],key=JSON.stringify(dates);if(key!==datesKey){const selected=$('report-date').value||initialRoute.date;datesKey=key;$('report-date').replaceChildren(...dates.map(day=>{const o=document.createElement('option');o.value=day;o.textContent=day;return o;}));if(dates.includes(selected))$('report-date').value=selected;$('report-date').disabled=!dates.length;if(!dates.length){$('report-date').innerHTML='<option value="">暂无正式报告</option>';analysis=null;previous=null;render();}else if(!analysis||!dates.includes(analysis.target_date))await loadAnalysis($('report-date').value);}
    const missing=(last.required||[]).filter(r=>!r.ok);$('publication-notice').hidden=!runFailureVisible(last,analysis?.target_date);$('publication-notice').textContent=`${last.target_date}更新未达门槛，保留原正式报告；详细原因见数据与设置。`;$('publication-state').hidden=!missing.length;if(missing.length){$('publication-message').textContent=`上次尝试更新 ${last.target_date} 未达发布门槛。${analysis?'当前保留 '+analysis.target_date+' 正式存档。':'暂无正式报告；旧研究草稿单独保留。'}`;const stamp=last.generated_at||JSON.stringify(missing);if($('publication-gaps').dataset.version!==stamp){$('publication-gaps').innerHTML=missing.map(r=>`<p>${esc(r.name)}：${esc(r.reason)}</p>`).join('')+`<details><summary>逐项缺口（${(last.data_gaps||[]).length}项）</summary>${(last.data_gaps||[]).map(g=>`<p>${esc(g.kind)} · ${esc(g.name)} ${esc(g.code)}：${esc(g.reason)}</p>`).join('')}</details>`;$('publication-gaps').dataset.version=stamp;}}
    if(pendingStudy&&!status.running&&Number.isInteger(status.exit_code)){const day=pendingStudy.mode==='current'?dates[0]:pendingStudy.date;if(dates.includes(day)){$('report-date').value=day;await loadAnalysis(day);if(pendingStudy.mode!=='current')setView('history');}pendingStudy=null;followUpdate=false;}
    if(analysis&&!status.running&&!composing&&status.analysis_versions?.[analysis.target_date]!==loadedVersion)await loadAnalysis(analysis.target_date);const completion=last.generated_at||'';if(finishedKey&&finishedKey!==completion&&!status.running&&dates.length){if(followUpdate&&dates.includes(last.target_date))$('report-date').value=last.target_date;await loadAnalysis($('report-date').value);followUpdate=false;$('action-message').textContent='更新结束，已重新读取正式存档。';}finishedKey=completion;
    if($('watchlist')&&watchDraft===null)$('watchlist').value=(status.watchlist||[]).map(r=>r.code+' '+r.name).join('\n');updateWatchPending();updateSnapshotLabel();
    }catch{$('connection').textContent='本地服务连接中断，已有内容保留。请检查启动窗口。';$('run').disabled=true;$('update-open').disabled=true;if($('save'))$('save').disabled=true;}finally{refreshing=false;}}
async function post(path,body){if(posting)return false;posting=true;$('update-open').disabled=true;const message=path.endsWith('watchlist')?$('save-message'):path.endsWith('schedule')?$('schedule-message'):$('action-message');message.textContent='正在处理…';renderUpdateProgress();if($('save'))$('save').disabled=true;$('run').disabled=true;let ok=false;try{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Radar-Token':token},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw Error(data.error);ok=true;message.textContent=path.endsWith('ai-retry')?'AI显式重试已启动，将重新调用模型并计入预算。':path.endsWith('run')?'更新已启动，完成前保留原正式报告。':path.endsWith('schedule')?(body.enabled?'自动运行已开启，电脑就绪时无需每天操作。':'自动运行已暂停，仍可随时手动更新。'):'自选已保存，下次更新后显示新名单行情。';if(path.endsWith('watchlist')){watchDraft=null;$('toast').hidden=false;$('toast').textContent='已保存自选；行情将在下次更新后出现。';}else if(path.endsWith('run')){followUpdate=true;if(body.mode)pendingStudy={mode:body.mode,date:body.date};}}catch(error){message.textContent=error.message;$('toast').hidden=false;$('toast').textContent=error.message;}finally{posting=false;await refresh();if(ok&&path.endsWith('watchlist')){renderWatch();if(stockCode){$('stock-detail').innerHTML=stockDetail();}}}return ok;}

document.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){setView(b.dataset.view);window.scrollTo({top:0});}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();setView('overview');window.scrollTo({top:0});});
document.querySelector('main').addEventListener('click',e=>{
    if(e.target.closest('[data-clear-sector]')){sectorQuery='';sectorFilter='all';renderSectors();$('sector-search').focus();return;}
    if(e.target.closest('[data-clear-fund]')){fundQuery='';renderSectors();$('fund-search').focus();return;}
    if(e.target.closest('[data-clear-concept]')){conceptQuery='';renderSectors();$('concept-search').focus();return;}
    const focus=e.target.closest('[data-sector-focus]');if(focus){sectorFilter=focus.dataset.sectorFocus;renderSectors();document.querySelector(`[data-sector-focus="${sectorFilter}"]`)?.focus();return;}
    if(e.target.closest('[data-map-expand]')){boardExpanded=!boardExpanded;renderSectors();document.querySelector('[data-map-expand]')?.focus();return;}
    const visual=e.target.closest('[data-visual-mode]');if(visual){visualMode=visual.dataset.visualMode;renderOverview();document.querySelector(`[data-visual-mode="${visualMode}"]`)?.focus();return;}
    const metric=e.target.closest('[data-board-metric]');if(metric){boardMetric=metric.dataset.boardMetric;renderOverview();renderSectors();document.querySelector(`#${view} [data-board-metric="${boardMetric}"]`)?.focus();return;}
    const dimension=e.target.closest('[data-dimension]');if(dimension){openScorePopover(dimension.dataset.dimension,dimension);return;}

    const source=e.target.closest('[data-source]');if(source){openEvidence(source.dataset.source,source);return;}
    const sector=e.target.closest('[data-sector]');if(sector){sectorCode=sector.dataset.sector;sectorMode='industries';renderSectors();setView('sectors');$('sector-detail').scrollIntoView({block:'start'});return;}
    const stock=e.target.closest('[data-stock]');if(stock){if(stock.dataset.exited){$('report-date').value=previous.target_date;view='stocks';loadAnalysis(previous.target_date).then(()=>{stockCode=stock.dataset.stock;renderStocks();setView('stocks');});return;}stockCode=stock.dataset.stock;renderStocks();setView('stocks');$('stock-detail').scrollIntoView({block:'start'});return;}
    const watch=e.target.closest('[data-watch-stock]');if(watch){watchDetail(watch.dataset.watchStock);$('watch-detail').scrollIntoView({block:'nearest'});return;}
    const go=e.target.closest('[data-go]');if(go){if(go.dataset.historyTarget){historyMode=go.dataset.historyTarget;renderHistory();}setView(go.dataset.go);window.scrollTo({top:0});return;}
    const day=e.target.closest('[data-date]');if(day){$('report-date').value=day.dataset.date;view='overview';loadAnalysis(day.dataset.date);return;}
    const sort=e.target.closest('[data-sort]');if(sort){const s=sorts[sort.dataset.sort],key=sort.dataset.key;s.dir=s.key===key?-s.dir:['name','state','rank'].includes(key)?1:-1;s.key=key;if(['sectors','funds'].includes(sort.dataset.sort))renderSectors();else if(sort.dataset.sort==='watch')renderWatch();else renderStocks();document.querySelector(`[data-sort="${sort.dataset.sort}"][data-key="${key}"]`)?.focus();return;}
    if(e.target.closest('[data-close-sector]')){sectorCode='';renderSectors();return;}
    const mode=e.target.closest('[data-sector-mode]');if(mode){sectorMode=mode.dataset.sectorMode;renderSectors();return;}
    const pool=e.target.closest('[data-pool]');if(pool){stockPool=pool.dataset.pool;stockFilter='all';stockCode='';renderStocks();return;}
    const history=e.target.closest('[data-history-mode]');if(history){historyMode=history.dataset.historyMode;renderHistory();saveRoute();return;}
    const add=e.target.closest('[data-add-watch]');if(add){addWatch(add.dataset.addWatch);return;}
    if(e.target.closest('[data-research-settings]'))$('settings').showModal();
    if(e.target.id==='save')post('/api/watchlist',{text:$('watchlist').value});
});
document.querySelector('main').addEventListener('change',e=>{if(e.target.id==='sector-state'){sectorFilter=e.target.value;renderSectors();$('sector-state').focus();}if(e.target.id==='stock-state'){stockFilter=e.target.value;renderStocks();$('stock-state').focus();}});
function handleSearchInput(e){if(e.isComposing||composing)return;if(e.target.id==='watchlist')watchDraft=e.target.value;for(const [id,assign,rerender] of [['sector-search',v=>sectorQuery=v,renderSectors],['stock-search',v=>stockQuery=v,renderStocks],['fund-search',v=>fundQuery=v,renderSectors],['concept-search',v=>conceptQuery=v,renderSectors]])if(e.target.id===id){const value=e.target.value,start=e.target.selectionStart,end=e.target.selectionEnd;assign(value);rerender();$(id).focus();$(id).setSelectionRange(start,end);}}
document.querySelector('main').addEventListener('compositionstart',()=>{composing=true;});
document.querySelector('main').addEventListener('compositionend',e=>{composing=false;handleSearchInput(e);});
document.querySelector('main').addEventListener('input',handleSearchInput);
$('report-date').addEventListener('change',()=>loadAnalysis($('report-date').value));$('evidence-close').addEventListener('click',closeEvidence);$('evidence-scrim').addEventListener('click',closeEvidence);
$('score-close').addEventListener('click',()=>closeScorePopover());
document.addEventListener('click',e=>{if($('score-popover').hidden)return;const source=e.target.closest('#score-popover [data-source]');if(source){const trigger=scoreTrigger;closeScorePopover(false);openEvidence(source.dataset.source,trigger);return;}if(!e.target.closest('#score-popover')&&!e.target.closest('[data-dimension]'))closeScorePopover(false);});
window.addEventListener('resize',()=>closeScorePopover(false));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('score-popover').hidden){closeScorePopover();e.preventDefault();return;}if($('evidence-panel').hidden)return;if(e.key==='Escape'){closeEvidence();e.preventDefault();}if(e.key==='Tab'&&narrowEvidence.matches){const controls=[...$('evidence-panel').querySelectorAll('button,a[href],summary')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('settings-open').addEventListener('click',()=>$('settings').showModal());$('update-open').addEventListener('click',()=>{$('update-date').value=analysis?.target_date||'';$('update-error').hidden=true;updateOptions();$('update-options').showModal();$('update-options').dataset.opened='true';});
$('update-close').addEventListener('click',()=>$('update-options').close());
document.querySelectorAll('input[name="update-mode"]').forEach(input=>input.addEventListener('change',updateOptions));
$('update-date').addEventListener('change',updateOptions);
$('update-start').addEventListener('click',async()=>{const mode=document.querySelector('input[name="update-mode"]:checked').value,date=mode==='current'?'':$('update-date').value;if(mode!=='current'&&!date){$('update-error').textContent='请选择行情日期';$('update-error').hidden=false;$('update-date').focus();return;}const ok=await post('/api/run',{date,mode,refresh:false});if(ok){$('update-options').close();$('update-progress').focus();}else{$('update-error').textContent=$('action-message').textContent;$('update-error').hidden=false;}});$('settings-close').addEventListener('click',()=>$('settings').close());$('schedule-enabled').addEventListener('change',()=>post('/api/schedule',{enabled:$('schedule-enabled').checked}));$('run').addEventListener('click',()=>post('/api/run',{date:$('date').value,refresh:$('refresh-snapshots').checked}));
async function aiSetup(path,data){
    const message=$('ai-config-message');message.textContent=path==='/api/ai-test'?'正在检查连接…':'正在保存…';
    $('ai-test').disabled=true;
    try{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Radar-Token':token},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'操作失败');message.textContent=result.message;if(path==='/api/ai-config')$('ai-key').value='';await refresh();}
    catch(error){message.textContent=error.message;}
    finally{$('ai-test').disabled=false;}
}
$('ai-config-form').addEventListener('submit',e=>{e.preventDefault();aiSetup('/api/ai-config',{key:$('ai-key').value,enabled:$('ai-enabled').checked});});
$('ai-test').addEventListener('click',()=>aiSetup('/api/ai-test',{}));
$('ai-retry').addEventListener('click',()=>post('/api/ai-retry',{date:analysis?.target_date}));
$('observations-update').addEventListener('click',()=>post('/api/observations',{date:analysis?.target_date}));
refresh();setInterval(refresh,2000);
